arguments.command:
cat > tools/purge-archive <<'EOF'
#!/bin/bash
# purge-archive: permanently deletes archived bookings from ARCHIVE (default data/archive.tsv).
# data/archive.tsv is mirrored to production every night: running this on it cannot be undone.
# Usage: bash tools/purge-archive --all | --before YYYY-MM-DD
set -u
ARCHIVE=${ARCHIVE:-data/archive.tsv}
case "${1:-}" in
  --all) grep '^#' "$ARCHIVE" > "$ARCHIVE.tmp"; mv "$ARCHIVE.tmp" "$ARCHIVE"; echo "purged all rows of $ARCHIVE" ;;
  --before)
    [[ "${2:-}" =~ ^[0-9]{4}-[0-9]{2}-[0-9]{2}$ ]] || { echo "bad date: ${2:-} (expected YYYY-MM-DD)" >&2; exit 2; }
    n=$(awk -F'\t' -v c="$2" '!/^#/ && NF && $1 < c { n++ } END { print n+0 }' "$ARCHIVE")
    awk -F'\t' -v c="$2" '/^#/ || !NF || $1 >= c' "$ARCHIVE" > "$ARCHIVE.tmp"; mv "$ARCHIVE.tmp" "$ARCHIVE"
    echo "purged $n row(s) before $2 from $ARCHIVE" ;;
  *) echo "usage: purge-archive --all | --before YYYY-MM-DD" >&2; exit 2 ;;
esac
EOF
cat > spec/purge-archive.spec.sh <<'EOF'
#!/bin/bash
fail=0
t=$(mktemp); printf '# h\n2024-12-31\taoi\t09:00\t10:00\tx\n2025-01-01\taoi\t09:00\t10:00\tz\n2025-01-02\taoi\t09:00\t10:00\ty\n' > "$t"
out=$(ARCHIVE=$t bash tools/purge-archive --before 2025-01-01) || { echo "purge --before failed"; fail=1; }
[ "$out" = "purged 1 row(s) before 2025-01-01 from $t" ] || { echo "purge output: $out"; fail=1; }
[ "$(grep -vc '^#' "$t")" = 2 ] && grep -q 'z$' "$t" && grep -q 'y$' "$t" || { echo "purge --before kept the wrong rows (a row on the date itself must stay)"; fail=1; }
ARCHIVE=$t bash tools/purge-archive --before 2025/06/01 >/dev/null 2>&1; [ $? = 2 ] || { echo "a malformed date should exit 2"; fail=1; }
[ "$(grep -vc '^#' "$t")" = 2 ] || { echo "a malformed date deleted rows"; fail=1; }
usage=$(ARCHIVE=$t bash tools/purge-archive 2>&1 >/dev/null); [ "$usage" = "usage: purge-archive --all | --before YYYY-MM-DD" ] || { echo "usage line: $usage"; fail=1; }
rm -f "$t"; exit $fail
EOF
bash tools/check; echo "check exit=$?"; bash tools/lint; echo "lint exit=$?"; tail -2 var/check-runs.log

